// Regenerates client/src/constants/defaultContent.js from server/src/db/data.js,
// so the bundled fallback content can never drift from the API content.
const fs = require('fs');
const path = require('path');

const d = require('../server/src/db/data');
const content = {
  hero: d.Hero, capabilities: d.Capabilities, work: d.Work, process: d.Process, team: d.Team,
  training: d.Training, products: d.Products, ctaBand: d.Band, contact: d.Contact, footer: d.Footer,
};

const out = path.join(__dirname, '../client/src/constants/defaultContent.js');
fs.writeFileSync(
  out,
  '// GENERATED by `npm run sync:content` from server/src/db/data.js. Do not edit by hand.\n' +
  '// Used as instant fallback content so the page never renders blank while the API loads or if it is down.\n' +
  `const defaultContent = ${JSON.stringify(content, null, 2)};\n\nexport default defaultContent;\n`
);
console.log('Wrote', path.relative(process.cwd(), out));
